// TestGetOrCreateEntireSessionID_InvalidUUID tests that invalid UUIDs fall back gracefully.
func TestGetOrCreateEntireSessionID_InvalidUUID(t *testing.T) {
	// Invalid UUID should still return a session ID (fallback behavior)
	// This tests that path traversal attempts don't cause panics or errors
	invalidInputs := []string{
		"../../../etc/passwd",
		"/etc/passwd",
		"not-a-valid-uuid",
	}

	for _, input := range invalidInputs {
		result := GetOrCreateEntireSessionID(input)
		if result == "" {
			t.Errorf("GetOrCreateEntireSessionID(%q) returned empty string, expected fallback", input)
		}
		// Result should contain the input (as fallback generates date-prefixed ID)
		if !strings.Contains(result, input) {
			t.Errorf("GetOrCreateEntireSessionID(%q) = %q, expected to contain input", input, result)
		}
	}
}
